class BankAccount:
    def __init__(self, account_number, balance, password):
        self.account_number = account_number  # public
        self._balance = balance               # protected
        self.__password = password            # private

    def get_balance(self):
        return self._balance

    def deposit(self, amount, password):
        if password == self.__password:
            if amount > 0:
                self._balance += amount
                return f"Deposited ${amount}. New balance: ${self._balance}"
            return "Invalid amount"
        return "Incorrect password"

    def withdraw(self, amount, password):
        if password == self.__password:
            if 0 < amount <= self._balance:
                self._balance -= amount
                return f"Withdrawn ${amount}. New balance: ${self._balance}"
            return "Insufficient funds or invalid amount"
        return "Incorrect password"

# Usage
account = BankAccount("12345", 1000, "secret123")
print(account.account_number)  # Public - accessible
print(account._balance)        # Protected - accessible but not recommended
# print(account.__password)    # Private - will cause AttributeError
print(account.get_balance())   # Using getter method
