class Student:
    def __init__(self, name, age):
        self._name = name
        self._age = age

    @property
    def name(self):
        return self._name

    @name.setter
    def name(self, value):
        if isinstance(value, str) and len(value.strip()) > 0:
            self._name = value.strip()
        else:
            raise ValueError("Name must be a non-empty string")

    @property
    def age(self):
        return self._age

    @age.setter
    def age(self, value):
        if isinstance(value, int) and 0 <= value <= 120:
            self._age = value
        else:
            raise ValueError("Age must be between 0 and 120")

# Usage
student = Student("John Doe", 20)
print(student.name)  # Using property getter
student.name = "Jane Smith"  # Using property setter
student.age = 21
# student.age = -5  # Will raise ValueError
```

