class Employee:
    def __init__(self, name, salary, department):
        self._name = name
        self._salary = 0
        self._department = department
        self._bonus = 0
        self._tax_rate = 0.15

        self.salary = salary  # Use setter for validation

    @property
    def name(self):
        return self._name

    @property
    def salary(self):
        return self._salary

    @salary.setter
    def salary(self, value):
        if isinstance(value, (int, float)) and value >= 0:
            self._salary = value
        else:
            raise ValueError("Salary must be a non-negative number")

    @property
    def department(self):
        return self._department

    @department.setter
    def department(self, value):
        valid_departments = ["IT", "HR", "Finance", "Marketing", "Sales"]
        if value in valid_departments:
            self._department = value
        else:
            raise ValueError(f"Department must be one of: {valid_departments}")

    def add_bonus(self, amount):
        if isinstance(amount, (int, float)) and amount >= 0:
            self._bonus += amount
            return f"Bonus of ${amount} added"
        raise ValueError("Bonus must be a non-negative number")

    def calculate_tax(self):
        taxable_income = self._salary + self._bonus
        return taxable_income * self._tax_rate

    def get_net_salary(self):
        tax = self.calculate_tax()
        return self._salary + self._bonus - tax

    def get_payroll_info(self):
        return {
            "name": self._name,
            "department": self._department,
            "base_salary": self._salary,
            "bonus": self._bonus,
            "tax": self.calculate_tax(),
            "net_salary": self.get_net_salary()
        }

# Usage
emp = Employee("Alice Johnson", 50000, "IT")
emp.add_bonus(5000)
emp.department = "Finance"
print(emp.get_payroll_info())
```

