class LibraryBook:
    def __init__(self, title, author, isbn, total_copies):
        self._title = ""
        self._author = ""
        self._isbn = ""
        self._total_copies = 0
        self._available_copies = 0
        self._borrowed_by = []

        # Use setters for validation
        self.title = title
        self.author = author
        self.isbn = isbn
        self.total_copies = total_copies

    @property
    def title(self):
        return self._title

    @title.setter
    def title(self, value):
        if isinstance(value, str) and len(value.strip()) >= 1:
            self._title = value.strip()
        else:
            raise ValueError("Title cannot be empty")

    @property
    def author(self):
        return self._author

    @author.setter
    def author(self, value):
        if isinstance(value, str) and len(value.strip()) >= 2:
            self._author = value.strip()
        else:
            raise ValueError("Author name must be at least 2 characters")

    @property
    def isbn(self):
        return self._isbn

    @isbn.setter
    def isbn(self, value):
        # Simple ISBN validation (10 or 13 digits)
        if isinstance(value, str) and value.replace("-", "").isdigit():
            digits = value.replace("-", "")
            if len(digits) in [10, 13]:
                self._isbn = value
            else:
                raise ValueError("ISBN must be 10 or 13 digits")
        else:
            raise ValueError("ISBN must contain only digits and hyphens")

    @property
    def total_copies(self):
        return self._total_copies

    @total_copies.setter
    def total_copies(self, value):
        if isinstance(value, int) and value > 0:
            self._total_copies = value
            self._available_copies = value
        else:
            raise ValueError("Total copies must be a positive integer")

    @property
    def available_copies(self):
        return self._available_copies

    def borrow_book(self, borrower):
        if self._available_copies > 0:
            self._available_copies -= 1
            self._borrowed_by.append(borrower)
            return f"'{self._title}' borrowed by {borrower}"
        return f"'{self._title}' is not available"

    def return_book(self, borrower):
        if borrower in self._borrowed_by:
            self._borrowed_by.remove(borrower)
            self._available_copies += 1
            return f"'{self._title}' returned by {borrower}"
        return f"{borrower} has not borrowed '{self._title}'"

    def get_status(self):
        return {
            "title": self._title,
            "author": self._author,
            "isbn": self._isbn,
            "total_copies": self._total_copies,
            "available_copies": self._available_copies,
            "borrowed_by": self._borrowed_by.copy()  # Return copy to prevent external modification
        }

# Usage
book = LibraryBook("Python Programming", "John Smith", "978-0-123456-47-2", 5)
print(book.borrow_book("Alice"))
print(book.borrow_book("Bob"))
print(book.get_status())
print(book.return_book("Alice"))
```
